-- Global exercise and food libraries (from src/domain/data). Nutrition values are approximate, from USDA FoodData Central.

on conflict (id) do update set name = excluded.name, muscle = excluded.muscle, region = excluded.region, equipment = excluded.equipment, instructions = excluded.instructions, alt_ids = excluded.alt_ids;

on conflict (id) do update set name = excluded.name, basis = excluded.basis, kcal = excluded.kcal, protein = excluded.protein, carbs = excluded.carbs, fat = excluded.fat, role = excluded.role, category = excluded.category, tags = excluded.tags, source = excluded.source, serving = excluded.serving, raw_id = excluded.raw_id, cooked_id = excluded.cooked_id, yield = excluded.yield, buy = excluded.buy;
