insert into public.exercises (id, name, muscle, region, equipment, instructions, alt_ids) values
  ('squat', 'Back squat', 'Quads', 'lower', 'Barbell', 'Bar on upper back, brace, sit down between the hips to depth you control, drive up through mid-foot.', array['hack','legpress','goblet']::text[]),
  ('rdl', 'Romanian deadlift', 'Hamstrings', 'lower', 'Barbell', 'Soft knees, push hips back keeping the bar close, stop when hamstrings limit range, stand tall.', array['dbrdl','legcurl']::text[]),
  ('legpress', 'Leg press', 'Quads', 'lower', 'Machine', 'Feet mid-platform, lower until hips start to tuck, press without locking knees hard.', array['hack','squat']::text[]),
  ('legcurl', 'Lying leg curl', 'Hamstrings', 'lower', 'Machine', 'Hips pinned, curl to full flexion, 2 s lowering.', array['seatcurl','rdl']::text[]),
  ('calf', 'Standing calf raise', 'Calves', 'lower', 'Machine', 'Full stretch at the bottom, pause, rise onto big toe.', '{}'),
  ('crunch', 'Cable crunch', 'Core', 'core', 'Cable', 'Kneel, rope by ears, flex the spine toward the floor, hips still.', array['kneeraise']::text[]),
  ('incdb', 'Incline DB press', 'Chest', 'upper', 'Dumbbell', 'Bench at 30°, shoulder blades set, lower to chest level, press slightly inward.', array['incbar','bench','fly']::text[]),
  ('csrow', 'Chest-supported row', 'Upper back', 'upper', 'Dumbbell', 'Chest on incline pad, row elbows toward hips, pause at the top.', array['dbrow','cablerow']::text[]),
  ('pulldown', 'Lat pulldown', 'Lats', 'upper', 'Cable', 'Slight lean back, drive elbows down to ribs, control the return to a full stretch.', array['ngpull','pullup']::text[]),
  ('dbsp', 'Seated DB shoulder press', 'Shoulders', 'upper', 'Dumbbell', 'Back supported, press up and slightly in, lower to ear height.', array['machsp']::text[]),
  ('lateral', 'Cable lateral raise', 'Shoulders', 'upper', 'Cable', 'Lead with the elbow, raise to shoulder height, slow lowering.', array['dblateral']::text[]),
  ('pushdown', 'Rope pushdown', 'Triceps', 'upper', 'Cable', 'Elbows fixed at sides, extend and split the rope at the bottom.', array['ohext']::text[]),
  ('hipthrust', 'Barbell hip thrust', 'Glutes', 'lower', 'Barbell', 'Upper back on bench, chin tucked, drive through heels to full hip extension, pause 1 s.', array['glutebridge','machthrust']::text[]),
  ('bss', 'Bulgarian split squat', 'Glutes', 'lower', 'Dumbbell', 'Rear foot on bench, torso slightly forward, lower under control. Weight is per dumbbell.', array['lunge','legpress']::text[]),
  ('hack', 'Hack squat', 'Quads', 'lower', 'Machine', 'Feet shoulder width, lower to depth, press through the whole foot.', array['legpress','squat']::text[]),
  ('seatcurl', 'Seated leg curl', 'Hamstrings', 'lower', 'Machine', 'Lean forward slightly for more stretch, curl fully, control up.', array['legcurl']::text[]),
  ('abduct', 'Hip abduction', 'Glutes', 'lower', 'Machine', 'Slight forward lean, push knees out, pause at the end.', '{}'),
  ('kneeraise', 'Hanging knee raise', 'Core', 'core', 'Bodyweight', 'Posterior pelvic tilt, raise knees to chest, no swing.', array['crunch']::text[]),
  ('bench', 'Bench press', 'Chest', 'upper', 'Barbell', 'Feet planted, slight arch, touch low chest, press back over shoulders.', array['incdb','machpress']::text[]),
  ('dbrow', 'One-arm DB row', 'Upper back', 'upper', 'Dumbbell', 'Hand and knee on bench, row toward hip, full stretch at the bottom.', array['csrow','cablerow']::text[]),
  ('ngpull', 'Neutral-grip pulldown', 'Lats', 'upper', 'Cable', 'Neutral handle, chest up, elbows to ribs.', array['pulldown']::text[]),
  ('fly', 'Machine chest fly', 'Chest', 'upper', 'Machine', 'Soft elbows, hug the arc, squeeze, slow return.', '{}'),
  ('facepull', 'Face pull', 'Rear delts', 'upper', 'Cable', 'Rope at face height, pull to forehead, rotate thumbs back.', '{}'),
  ('ezcurl', 'EZ-bar curl', 'Biceps', 'upper', 'Barbell', 'Elbows still, curl up, 2 s down.', array['dbcurl']::text[]),
  ('goblet', 'Goblet squat', 'Quads', 'lower', 'Dumbbell', 'Hold DB at chest, sit between hips, elbows inside knees.', array['squat']::text[]),
  ('dbrdl', 'DB Romanian deadlift', 'Hamstrings', 'lower', 'Dumbbell', 'As the barbell RDL, dumbbells along the thighs.', array['rdl']::text[]),
  ('incbar', 'Incline barbell press', 'Chest', 'upper', 'Barbell', '30° bench, bar to upper chest.', array['incdb']::text[]),
  ('machpress', 'Machine chest press', 'Chest', 'upper', 'Machine', 'Handles at mid-chest, press without shrugging.', array['bench']::text[]),
  ('cablerow', 'Seated cable row', 'Upper back', 'upper', 'Cable', 'Tall chest, row to lower ribs, stretch forward.', array['csrow']::text[]),
  ('pullup', 'Assisted pull-up', 'Lats', 'upper', 'Machine', 'Weight shown is assistance — lower is harder.', array['pulldown']::text[]),
  ('machsp', 'Machine shoulder press', 'Shoulders', 'upper', 'Machine', 'Seat so handles start at shoulder height.', array['dbsp']::text[]),
  ('dblateral', 'DB lateral raise', 'Shoulders', 'upper', 'Dumbbell', 'Slight lean forward, raise to shoulder height.', array['lateral']::text[]),
  ('ohext', 'Overhead cable extension', 'Triceps', 'upper', 'Cable', 'Face away, elbows forward, extend fully.', array['pushdown']::text[]),
  ('glutebridge', 'DB glute bridge', 'Glutes', 'lower', 'Dumbbell', 'Floor bridge with DB on hips.', array['hipthrust']::text[]),
  ('machthrust', 'Hip thrust machine', 'Glutes', 'lower', 'Machine', 'Pad across hips, drive to lockout.', array['hipthrust']::text[]),
  ('lunge', 'Walking lunge', 'Glutes', 'lower', 'Dumbbell', 'Long step, back knee toward floor. Weight per dumbbell.', array['bss']::text[]),
  ('dbcurl', 'Incline DB curl', 'Biceps', 'upper', 'Dumbbell', 'Arms hang behind torso, curl without swinging.', array['ezcurl']::text[]),
  ('deadlift', 'Conventional deadlift', 'Posterior chain', 'lower', 'Barbell', 'Bar over mid-foot, wedge in, push the floor away.', array['rdl']::text[]),
  ('legext', 'Leg extension', 'Quads', 'lower', 'Machine', 'Pause at the top, 3 s lowering.', '{}')
